import os
from pathlib import Path
from urllib.parse import quote

# The secret key is generated by superset-init on first start and kept in the superset_home volume
_secret_file = Path(os.environ.get("SUPERSET_HOME", "/app/superset_home")) / "secret_key"
SECRET_KEY = os.environ.get("SUPERSET_SECRET_KEY") or (_secret_file.read_text().strip() if _secret_file.exists() else "")

# The metadata database lives on the same Postgres server as the OMOP database
SQLALCHEMY_DATABASE_URI = "postgresql+psycopg2://superset:{password}@{host}:{port}/superset".format(
    password=quote(os.environ["SUPERSET_DB_PASSWORD"], safe=""),
    host=os.environ.get("OMOP_DB_HOST", "postgres"),
    port=os.environ.get("OMOP_DB_PORT", "5432"),
)
